# ============================================================
#  Porofessor NoAds Daemon  (pure PowerShell - NO Node.js needed)
#  Speaks Chrome DevTools Protocol via the built-in .NET
#  System.Net.WebSockets.ClientWebSocket. Blocks ad networks and
#  injects CSS that hides ad slots + reclaims the ad column.
#  Touches NOTHING inside the app bundle -> no anti-tamper issue.
# ============================================================
$ErrorActionPreference = 'SilentlyContinue'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

# ---- config ----------------------------------------------------------------
$PORT       = 9333
$IP         = '127.0.0.1'
$TASK       = 'PorofessorNoAds'
$MUTEX_NAME = 'Global\PorofessorNoAds.singleton'
$YIELD_NAME = 'Global\PorofessorNoAds.yield'
$APP_IMAGE  = 'Porofessor Standalone.exe'
$DIR        = $PSScriptRoot
if (-not $DIR) { $DIR = Split-Path -Parent $MyInvocation.MyCommand.Path }
$FLAGS      = Join-Path $DIR 'poro-flags.ps1'
$LAUNCHER   = Join-Path $DIR 'poro-launcher.vbs'
$WSCRIPT    = Join-Path $env:SystemRoot 'System32\wscript.exe'

$BLOCK = @(
  '*doubleclick.net*','*googlesyndication*','*googletagservices*','*googleadservices*',
  '*googletagmanager.com*','*amazon-adsystem*','*adnxs*','*pubmatic*','*rubiconproject*',
  '*casalemedia*','*33across*','*smartadserver*','*yieldlab*','*onetag-sys*','*criteo*',
  '*sharethrough*','*3lift*','*media.net*','*indexww*','*sonobi*','*gumgum*','*teads*',
  '*openx*','*yieldmo*','*adform.net*','*smilewanted*','*admatic.de*','*2mdn.net*',
  '*adsrvr.org*','*ad.gt*','*360yield*','*geoedge*','*arttrk*','*bttrack*','*moatads*',
  '*adsafeprotected*','*simpli.fi*','*ads.linkedin.com*','*content.overwolf.com/libs/ads/*',
  '*leagueofgraphs.com/*/overwolf/no-local-profile*','*leagueofgraphs.com/*showAdSpace*'
)

# Injector: hide ad surfaces + reclaim the reserved ad column (the app's own
# removeAdsSpace state) + stretch the leagueofgraphs profile to full width.
$INJECTOR = @'
(function(){
  if (window.__poroNoAds) return; window.__poroNoAds = 1;
  var POROTITLE = "data:image/png;base64,";
  var POROLOGO = "data:image/png;base64,";
  var HIDE = "#ad-container,#ad-strip,#ad-div,#ad-div-top,#ad-div-strip,#ad-div-secondary,#ad-div-container,[id^='ad-div'],.adContainer,#bannerFrame,[class*='ad-container'],[id*='ad-container'],.adcontainer,[class*='adSpace'],[id*='adSpace'],[class*='AdSlot'],.overwolfBanner,.overwolfBanner--profile,iframe[src*='showAdSpace'],iframe[src*='/overwolf/no-local-profile'],iframe[src*='doubleclick'],iframe[src*='googlesyndication'],iframe[src*='amazon-adsystem']{display:none !important;width:0 !important;height:0 !important;min-height:0 !important;max-height:0 !important;}";
  var WIDEN = ".home--desktop #iframe-porofessor,.home--ingame #iframe-porofessor{padding-right:0 !important;}.home--desktop #iframe-overlay,.home--ingame #iframe-overlay{width:100% !important;}.home--desktop #nonModalDialog-overlay,.home--ingame #nonModalDialog-overlay{width:100% !important;}.home-meta #iframe-porofessor{padding-right:0 !important;width:100% !important;left:0 !important;}body>.row,main,.row.overwolfSummonerPage,.medium-24.columns.profileContent,.profileContent{max-width:none !important;width:100% !important;}.profileContentColumn1{width:54% !important;max-width:none !important;}.profileContentColumn2{width:45% !important;max-width:none !important;}.profileContentColumn1 .box,.profileContentColumn2 .box,.profileContent .box,.profileContent .data_table{width:100% !important;max-width:none !important;}.profileContent.mt-110{margin-top:0 !important;}#lowerNavigationBar{width:auto !important;left:24px !important;right:24px !important;}.profileContent{padding-left:24px !important;padding-right:24px !important;box-sizing:border-box !important;}";
  var FONT = "@import url('https://fonts.googleapis.com/css2?family=UnifrakturMaguntia&display=swap');";
  var CSS = FONT + HIDE + WIDEN;
  function ensureStyle(){
    var s = document.getElementById('__poro_noads_css');
    if (!s){ s = document.createElement('style'); s.id='__poro_noads_css'; (document.head||document.documentElement).appendChild(s); }
    if (s.textContent !== CSS) s.textContent = CSS;
  }
  function collapse(){
    try{
      var ifr = document.querySelectorAll("iframe[src*='showAdSpace'],iframe[src*='/overwolf/no-local-profile']");
      for (var i=0;i<ifr.length;i++){ var node = ifr[i];
        for (var k=0;k<4 && node.parentElement;k++){ var r=node.parentElement.getBoundingClientRect();
          if (r.height>0 && r.height<400 && r.width>200) node=node.parentElement; else break; }
        if (node.style.display !== 'none') node.style.setProperty('display','none','important');
      }
    }catch(e){}
  }
  function premiumGate(){
    var on = /\/store(\/|$)|\/premium(\/|$)/i.test(location.pathname);
    var ov = document.getElementById('__de_staatseigentum');
    if (on){
      if (!ov){
        ov = document.createElement('div'); ov.id = '__de_staatseigentum';
        ov.style.cssText = 'position:fixed;inset:0;z-index:2147483647;display:flex;align-items:center;justify-content:center;background:linear-gradient(#000 0 33.333%,#DD0000 33.333% 66.666%,#FFCE00 66.666% 100%);overflow:hidden;';
        var t = document.createElement('div');
        t.textContent = 'Diese Seite ist nun Staatseigentum der Bundesrepublik Deutschland.';
        t.style.cssText = "font-family:'UnifrakturMaguntia','Old English Text MT','Cloister Black','Fette Fraktur','Fraktur',serif;font-size:3vw;line-height:1.3;color:#fff;text-align:center;max-width:84%;text-shadow:0 3px 12px rgba(0,0,0,.92),0 0 3px #000;letter-spacing:.5px;";
        ov.appendChild(t);
        (document.body||document.documentElement).appendChild(ov);
      }
      ov.style.display = 'flex';
    } else if (ov){ ov.style.display = 'none'; }
  }
  function swapLogo(){ try{ var l=document.getElementById("porofessorLogo"); if(l && l.getAttribute("src")!==POROLOGO){ l.src=POROLOGO; l.style.objectFit="contain"; } var t=document.getElementById("porofessorTitle"); if(t && t.getAttribute("src")!==POROTITLE){ t.src=POROTITLE; t.style.objectFit="contain"; t.style.setProperty("height","26px","important"); t.style.setProperty("width","auto","important"); } }catch(e){} }
  function apply(){ try{ ensureStyle(); collapse(); premiumGate(); swapLogo(); }catch(e){} }
  var pending=false;
  function schedule(){ if(pending)return; pending=true; (window.requestAnimationFrame||setTimeout)(function(){ pending=false; apply(); }); }
  apply();
  try{ new MutationObserver(schedule).observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['class','style','src']}); }catch(e){}
  document.addEventListener('DOMContentLoaded', apply);
  setInterval(apply, 400);
  setInterval(premiumGate, 350);
})();
'@

# ---- logging ---------------------------------------------------------------
function Log([string]$m){ try { [Console]::Out.WriteLine('[poro-noads] ' + $m) } catch {} }

# ---- elevation + singleton (named mutex, liveness-based) -------------------
function Test-Elevated {
  try { (New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())).IsInRole([Security.Principal.WindowsBuiltinRole]::Administrator) }
  catch { $true }  # fail-open: if we cannot tell, run rather than defer
}
$elevated = Test-Elevated
$createdNew = $false
$mutex = New-Object System.Threading.Mutex($true, $MUTEX_NAME, [ref]$createdNew)
$yield = New-Object System.Threading.EventWaitHandle($false, [System.Threading.EventResetMode]::ManualReset, $YIELD_NAME)
if (-not $createdNew) {
  # A daemon is already alive (liveness, not mere task existence).
  if ($elevated) {
    # Elevated copy takes over from a non-elevated holder: signal yield, then grab.
    $yield.Set() | Out-Null
    if (-not $mutex.WaitOne(6000)) { Log 'could not take over singleton -> exit'; exit }
    $yield.Reset() | Out-Null
    Log 'took over singleton as elevated'
  } else {
    Log 'another daemon owns the singleton -> deferring'; exit
  }
}

# ---- CDP plumbing ----------------------------------------------------------
$script:ws = $null
$script:connected = $false
$script:wsUrl = $null
$script:cmdId = 0
$ct = [Threading.CancellationToken]::None

function Http-Json([string]$path){
  try {
    $r = Invoke-RestMethod -Uri ("http://{0}:{1}{2}" -f $IP,$PORT,$path) -TimeoutSec 4
    return $r
  } catch { return $null }
}
function Send-Cdp([string]$method, $params, [string]$session){
  if (-not $script:ws -or $script:ws.State -ne 'Open') { return }
  $script:cmdId++
  $o = @{ id = $script:cmdId; method = $method }
  if ($params) { $o.params = $params } else { $o.params = @{} }
  if ($session) { $o.sessionId = $session }
  $json = $o | ConvertTo-Json -Compress -Depth 8
  try {
    $bytes = [Text.Encoding]::UTF8.GetBytes($json)
    $seg = [System.ArraySegment[byte]]::new($bytes)
    [void]$script:ws.SendAsync($seg, [System.Net.WebSockets.WebSocketMessageType]::Text, $true, $ct).GetAwaiter().GetResult()
  } catch {}
}
function Configure-Session([string]$s){
  Send-Cdp 'Network.enable' $null $s
  Send-Cdp 'Network.setBlockedURLs' @{ urls = $BLOCK } $s
  Send-Cdp 'Page.enable' $null $s
  Send-Cdp 'Page.addScriptToEvaluateOnNewDocument' @{ source = $INJECTOR } $s
  Send-Cdp 'Runtime.evaluate' @{ expression = $INJECTOR } $s
  Send-Cdp 'Target.setAutoAttach' @{ autoAttach=$true; waitForDebuggerOnStart=$true; flatten=$true } $s
  Send-Cdp 'Runtime.runIfWaitingForDebugger' $null $s
}
function Cleanup-Ws {
  if ($script:ws) { try { $script:ws.Abort() } catch {}; try { $script:ws.Dispose() } catch {} }
  $script:ws = $null; $script:connected = $false; $script:wsUrl = $null
}
function Connect-Cdp {
  $v = Http-Json '/json/version'
  if (-not $v -or -not $v.webSocketDebuggerUrl) { return }
  # if already connected to the SAME endpoint, keep it; else (re)connect cleanly
  if ($script:connected -and $script:wsUrl -eq $v.webSocketDebuggerUrl -and $script:ws.State -eq 'Open') { return }
  Cleanup-Ws
  try {
    $w = New-Object System.Net.WebSockets.ClientWebSocket
    $w.ConnectAsync([Uri]$v.webSocketDebuggerUrl, $ct).GetAwaiter().GetResult() | Out-Null
    $script:ws = $w; $script:wsUrl = $v.webSocketDebuggerUrl; $script:connected = $true
    Log 'connected to browser endpoint'
    Send-Cdp 'Target.setAutoAttach' @{ autoAttach=$true; waitForDebuggerOnStart=$true; flatten=$true } $null
  } catch { Cleanup-Ws }
}
function Handle-Message([string]$txt){
  if ($txt -notmatch 'attachedToTarget') { return }
  try { $m = $txt | ConvertFrom-Json } catch { return }
  if ($m.method -eq 'Target.attachedToTarget' -and $m.params.sessionId) { Configure-Session $m.params.sessionId }
}

# ---- lifecycle + heal (process-dependent, bounded) -------------------------
$HEAL_GRACE    = 15000
$HEAL_COOLDOWN = 45000
$MAX_HEALS     = 5
$EXIT_GRACE    = 90000   # die ~90s after the app is truly gone (survives update relaunch gaps)
$REASSERT_MS   = 20000

$script:lastSeen = [Environment]::TickCount
$script:appGoneSince = 0
$script:portDownSince = 0
$script:lastHeal = 0
$script:healCount = 0
$script:lastReassert = 0

function App-MainPid {
  $p = Get-CimInstance Win32_Process -Filter "Name='$APP_IMAGE'" -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -notmatch '--type=' } | Select-Object -First 1
  if ($p) { return $p.ProcessId } else { return $null }
}
function App-Present { [bool](Get-CimInstance Win32_Process -Filter "Name='$APP_IMAGE'" -ErrorAction SilentlyContinue | Select-Object -First 1) }

function Heal {
  $script:lastHeal = [Environment]::TickCount; $script:healCount++
  Log ("port dead while app runs -> clean restart via launcher ({0}/{1})" -f $script:healCount,$MAX_HEALS)
  $mp = App-MainPid
  if ($mp) { & taskkill /PID $mp /T /F 2>$null | Out-Null } else { & taskkill /IM $APP_IMAGE /T /F 2>$null | Out-Null }
  Start-Sleep -Milliseconds 1500
  try { Start-Process $WSCRIPT -ArgumentList ('"'+$LAUNCHER+'" --hidden-launch') -WindowStyle Hidden } catch {}
  $script:portDownSince = 0
}
function Reassert {
  $now = [Environment]::TickCount
  if (($now - $script:lastReassert) -lt $REASSERT_MS) { return }
  $script:lastReassert = $now
  try { Start-Process powershell.exe -ArgumentList '-NoProfile','-ExecutionPolicy','Bypass','-File',$FLAGS -WindowStyle Hidden } catch {}
}
function Periodic([bool]$portUp){
  Reassert
  # hand off to an elevated claimant
  if (-not $elevated -and $yield.WaitOne(0)) { Log 'yielding singleton to elevated daemon'; Cleanup-Ws; exit }
  $now = [Environment]::TickCount
  if ($portUp) { $script:lastSeen = $now; $script:appGoneSince = 0; $script:portDownSince = 0; $script:healCount = 0; return }
  if (-not $script:portDownSince) { $script:portDownSince = $now }
  if (App-Present) {
    $script:lastSeen = $now; $script:appGoneSince = 0
    if ((($now - $script:portDownSince) -gt $HEAL_GRACE) -and (($now - $script:lastHeal) -gt $HEAL_COOLDOWN) -and ($script:healCount -lt $MAX_HEALS)) { Heal }
    elseif (($script:healCount -ge $MAX_HEALS) -and (($now - $script:lastHeal) -gt ($HEAL_COOLDOWN * 5))) { $script:healCount = 0 } # back-off, retry later
  } else {
    if (-not $script:appGoneSince) { $script:appGoneSince = $now }
    $script:portDownSince = 0; $script:healCount = 0
    if (($now - $script:appGoneSince) -gt $EXIT_GRACE) { Log 'app gone -> exit (process-dependent)'; Cleanup-Ws; exit }
  }
}

# ---- main loop (crash-safe) ------------------------------------------------
Log ("daemon started (PowerShell, no Node), polling DevTools on {0}:{1}" -f $IP,$PORT)
$buf = New-Object byte[] 16384
$seg = [System.ArraySegment[byte]]::new($buf)
$sb = New-Object Text.StringBuilder
$pending = $null
$lastPeriodic = 0
while ($true) {
  try {
    if (-not $script:connected) {
      Connect-Cdp
      Periodic $script:connected
      if (-not $script:connected) { Start-Sleep -Milliseconds 1500 }
      continue
    }
    if (-not $pending) {
      if ($script:ws.State -ne 'Open') { Cleanup-Ws; continue }
      $pending = $script:ws.ReceiveAsync($seg, $ct)
    }
    if ($pending.IsCompleted) {
      $r = $null
      try { $r = $pending.GetAwaiter().GetResult() } catch { $r = $null }
      $pending = $null
      if ($null -eq $r -or $r.MessageType -eq [System.Net.WebSockets.WebSocketMessageType]::Close -or $script:ws.State -ne 'Open') {
        Cleanup-Ws; continue
      }
      [void]$sb.Append([Text.Encoding]::UTF8.GetString($buf, 0, $r.Count))
      if ($r.EndOfMessage) { $full = $sb.ToString(); [void]$sb.Clear(); Handle-Message $full }
    } else {
      $now = [Environment]::TickCount
      if (($now - $lastPeriodic) -ge 2000) { $lastPeriodic = $now; Periodic $true }
      Start-Sleep -Milliseconds 150
    }
  } catch {
    Log ('loop error: ' + $_.Exception.Message)
    Cleanup-Ws
    Start-Sleep -Milliseconds 1000
  }
}
